@shader #halftone_dots {
  @uniform density: float(2,12,6);
  @uniform size: float(.01,.15,.05);
  @uniform phase: float(0,6.283185307179586,0);
  @uniform ink: float(0,1,.9);
  @let x: float(fract(fract(uv_u)*density+phase*.15915494309189535)-.5);
  @let y: float(fract(fract(uv_v)*density)-.5);
  @let distance2: float(pow(abs(x),2)+pow(abs(y),2));
  @let dot: float(1-smoothstep(.01,.015,distance2-size));
  @fragment { color: mix(#F3EAD7,#182F43,dot*ink); }
}

